INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Ausgabedaten immer das Endergebnis eines Programms?', 2, '[{"text": "Nein", "correct": true, "because": "Können auch Zwischenergebnisse sein"}, {"text": "Ja", "correct": false, "because": "Nicht immer endgültig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Ausgabedaten?', 3, '[{"text": "Ergebnisse darstellen", "correct": true, "because": "Zeigt Verarbeitungsergebnisse"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Nicht primär"}, {"text": "Speicherplatz sparen", "correct": false, "because": "Kein Hauptziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu Ausgabedaten?', 5, '[{"text": "Formatierte Ergebnisse", "correct": true, "because": "Lesbar dargestellt"}, {"text": "Verarbeitete Eingaben", "correct": true, "because": "Basieren auf Eingabedaten"}, {"text": "Hardwarekonfiguration", "correct": false, "because": "Kein direkter Bestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ausgabedaten können in Dateien gespeichert werden. b) Sie sind immer visuell dargestellt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht immer visuell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Verarbeitung von Ausgabedaten?', 4, '[{"text": "Formatierung", "correct": false, "because": "Wichtig für Lesbarkeit"}, {"text": "Ausgabeziel", "correct": false, "because": "z.B. Datei oder Bildschirm"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Ausgabedaten in Echtzeit generiert werden können?', 2, '[{"text": "Ja", "correct": true, "because": "Live-Ausgabe möglich"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format ist typisch für Ausgabedaten?', 3, '[{"text": "Text", "correct": true, "because": "Häufig genutzt"}, {"text": "Bild", "correct": false, "because": "Weniger üblich"}, {"text": "Hardwarecode", "correct": false, "because": "Kein Ausgabeformat"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Handhabung von Ausgabedaten?', 5, '[{"text": "Formatierung", "correct": true, "because": "Macht Daten lesbar"}, {"text": "Ausgabeziel", "correct": true, "because": "z.B. Datei oder Konsole"}, {"text": "Produktwerbung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ausgabedaten sind das Ergebnis von Eingabedaten. b) Sie sind immer in Binärcode. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Format variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Ausgabedaten unwichtig?', 4, '[{"text": "Lesbarkeit", "correct": false, "because": "Entscheidend für Nutzung"}, {"text": "Ausgabeformat", "correct": false, "because": "Bestimmt Darstellung"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Können Ausgabedaten in einer Datenbank gespeichert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Speicherung möglich"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten gut gestaltete Ausgabedaten?', 4, '[{"text": "Verständlichkeit", "correct": true, "because": "Klarheit für Nutzer"}, {"text": "Weiterverarbeitung", "correct": true, "because": "Einfache Nutzung"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Ausgabedaten immer sichtbar sein müssen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Können unsichtbar gespeichert sein"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend sichtbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Ausgabedaten?', 3, '[{"text": "Klarheit", "correct": true, "because": "Verständlichkeit wichtig"}, {"text": "Schnelligkeit", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ausgabedaten können formatiert werden. b) Sie sind immer numerisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Können auch Text sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile haben schlecht gestaltete Ausgabedaten?', 5, '[{"text": "Schwierige Lesbarkeit", "correct": true, "because": "Unklare Darstellung"}, {"text": "Fehlende Nutzbarkeit", "correct": true, "because": "Schwer weiterzuverarbeiten"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Ausgabedaten unwichtig?', 3, '[{"text": "Format", "correct": false, "because": "Beeinflusst Nutzung"}, {"text": "Zielmedium", "correct": false, "because": "Entscheidet Ausgabe"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Können Ausgabedaten protokolliert werden?', 3, '[{"text": "Ja", "correct": true, "because": "Logging möglich"}, {"text": "Nein", "correct": false, "because": "Häufig genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Ausgabedaten in verschiedenen Formaten sein können?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. Text, CSV"}, {"text": "Nein", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel wähle ich für Ausgabedaten?', 4, '[{"text": "Datei", "correct": true, "because": "Speicherung möglich"}, {"text": "Bildschirm", "correct": false, "because": "Auch möglich, aber nicht allein"}, {"text": "Dekoration", "correct": false, "because": "Kein Bezug"}]');
